<?php
declare(strict_types=1); define('SAAS_NO_GLOBAL_NAV',true); require_once __DIR__.'/finance.php'; require_finance_admin(); $pdo=db();
if(($_GET['export']??'')==='csv'){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="client-report.csv"');$out=fopen('php://output','w');fputcsv($out,['Client','Invoiced','Received','Pending','Content count','Approval rate','Employees']);$data=$pdo->query("SELECT c.name,COALESCE((SELECT SUM(invoice_amount) FROM client_payments p WHERE p.client_id=c.id),0) invoiced,COALESCE((SELECT SUM(amount_received) FROM client_payments p WHERE p.client_id=c.id),0) received,COALESCE((SELECT SUM(pending_amount) FROM client_payments p WHERE p.client_id=c.id),0) pending,COUNT(DISTINCT ct.id) content_count,ROUND(100*SUM(ct.status='approved')/NULLIF(COUNT(ct.id),0),1) approval_rate,GROUP_CONCAT(DISTINCT u.name SEPARATOR ', ') employees FROM clients c LEFT JOIN content ct ON ct.client_id=c.id LEFT JOIN client_employees ce ON ce.client_id=c.id LEFT JOIN users u ON u.id=ce.employee_id GROUP BY c.id,c.name ORDER BY c.name");foreach($data as $row)fputcsv($out,$row);exit;}
$rows=$pdo->query("SELECT c.name,COALESCE((SELECT SUM(invoice_amount) FROM client_payments p WHERE p.client_id=c.id),0) invoiced,COALESCE((SELECT SUM(amount_received) FROM client_payments p WHERE p.client_id=c.id),0) received,COALESCE((SELECT SUM(pending_amount) FROM client_payments p WHERE p.client_id=c.id),0) pending,COUNT(DISTINCT ct.id) content_count,ROUND(100*SUM(ct.status='approved')/NULLIF(COUNT(ct.id),0),1) approval_rate,GROUP_CONCAT(DISTINCT u.name SEPARATOR ', ') employees FROM clients c LEFT JOIN content ct ON ct.client_id=c.id LEFT JOIN client_employees ce ON ce.client_id=c.id LEFT JOIN users u ON u.id=ce.employee_id GROUP BY c.id,c.name ORDER BY c.name")->fetchAll();function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html><head><meta charset="utf-8"><title>Client Report</title><link rel="stylesheet" href="assets/css/saas.css"></head><body class="saas-body"><div class="saas-shell"><aside class="saas-sidebar"><div class="brand"><span>MT</span> Mega Techzy</div><a class="saas-nav" href="admin_dashboard.php">▦ <span>Overview</span></a><a class="saas-nav active" href="client_report.php">▤ <span>Client report</span></a><a class="saas-nav" href="finance_report.php">⇩ <span>Finance export</span></a><a class="saas-nav" href="logout.php">↪ <span>Log out</span></a></aside><main class="saas-main"><h1 class="saas-title">Client Business Report</h1><p><a class="btn-indigo" href="client_report.php?export=csv">Export Excel-compatible CSV</a> <button class="btn-outline-indigo" onclick="window.print()">Print / Save PDF</button></p><section class="saas-card"><table class="saas-table"><thead><tr><th>Client</th><th>Invoiced</th><th>Received</th><th>Pending</th><th>Content</th><th>Approval</th><th>Employees</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['name'])?></td><td><?=inr($row['invoiced'])?></td><td><?=inr($row['received'])?></td><td><?=inr($row['pending'])?></td><td><?=e((string)$row['content_count'])?></td><td><?=e((string)($row['approval_rate']??0))?>%</td><td><?=e($row['employees']??'')?></td></tr><?php endforeach;?></tbody></table></section></main></div></body></html>
